-- FASE 1.3: aplicar somente após criar o projeto Supabase e revisar as policies.
create extension if not exists pgcrypto;
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, email text unique, name text, role text not null default 'admin' check (role in ('admin','editor')), avatar_url text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.clients (id uuid primary key default gen_random_uuid(), name text not null, email text, whatsapp text, notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.categories (id uuid primary key default gen_random_uuid(), slug text unique not null, name text not null, description text, sort_order int not null default 0, active boolean not null default true, created_at timestamptz not null default now());
create table public.galleries (id uuid primary key default gen_random_uuid(), slug text unique not null, title text not null, subtitle text, description text, story text, category_id uuid references public.categories(id), client_id uuid references public.clients(id), event_date date, location text, visibility text not null default 'private' check (visibility in ('public','private','unlisted')), password_hash text, download_enabled boolean not null default false, download_resolution text not null default 'web' check (download_resolution in ('web','full','both')), watermark_enabled boolean not null default false, comments_enabled boolean not null default false, favorites_enabled boolean not null default true, sharing_enabled boolean not null default false, featured boolean not null default false, featured_until timestamptz, sort_order int not null default 0, metadata jsonb not null default '{}', published_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.photos (id uuid primary key default gen_random_uuid(), gallery_id uuid not null references public.galleries(id) on delete cascade, filename text not null, storage_path text not null, path_thumbnail text, path_preview text, path_web text, path_watermark text, width int, height int, size_bytes bigint, format text, alt_text text, caption text, exif jsonb, sort_order int not null default 0, is_cover boolean not null default false, is_featured boolean not null default false, published boolean not null default true, processing_status text not null default 'pending' check (processing_status in ('pending','processing','done','error')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.gallery_access (id uuid primary key default gen_random_uuid(), gallery_id uuid not null references public.galleries(id) on delete cascade, client_id uuid references public.clients(id), token text unique not null default encode(gen_random_bytes(24), 'hex'), expires_at timestamptz, created_at timestamptz not null default now());
create table public.favorites (id uuid primary key default gen_random_uuid(), photo_id uuid not null references public.photos(id) on delete cascade, gallery_id uuid not null references public.galleries(id) on delete cascade, client_id uuid references public.clients(id), session_token text, created_at timestamptz not null default now(), check (client_id is not null or session_token is not null));
alter table public.profiles enable row level security; alter table public.clients enable row level security; alter table public.categories enable row level security; alter table public.galleries enable row level security; alter table public.photos enable row level security; alter table public.gallery_access enable row level security; alter table public.favorites enable row level security;
create policy "public sees published galleries" on public.galleries for select using (visibility = 'public' and published_at is not null and published_at <= now());
create policy "admins manage galleries" on public.galleries for all using (exists (select 1 from public.profiles p where p.id = auth.uid() and p.role in ('admin','editor')));
create policy "public sees published photos" on public.photos for select using (published and exists (select 1 from public.galleries g where g.id = gallery_id and g.visibility = 'public' and g.published_at is not null and g.published_at <= now()));
create policy "admins manage photos" on public.photos for all using (exists (select 1 from public.profiles p where p.id = auth.uid() and p.role in ('admin','editor')));
-- Privadas: acesso deve passar por endpoint servidor que valida token/PIN; não há policy pública ampla.
create table public.comments (id uuid primary key default gen_random_uuid(), photo_id uuid not null references public.photos(id) on delete cascade, gallery_id uuid not null references public.galleries(id) on delete cascade, client_id uuid references public.clients(id), session_token text, body text not null check (length(trim(body)) between 1 and 2000), read_by_admin boolean not null default false, created_at timestamptz not null default now(), check (client_id is not null or session_token is not null));
create table public.downloads (id uuid primary key default gen_random_uuid(), photo_id uuid references public.photos(id) on delete set null, gallery_id uuid references public.galleries(id) on delete set null, client_id uuid references public.clients(id) on delete set null, session_token text, resolution text check (resolution in ('web','full')), downloaded_at timestamptz not null default now(), ip_hash text);
create table public.messages (id uuid primary key default gen_random_uuid(), name text not null, email text, whatsapp text, work_type text, event_date date, city text, body text not null check (length(trim(body)) between 1 and 5000), read boolean not null default false, archived boolean not null default false, created_at timestamptz not null default now());
create table public.settings (key text primary key, value jsonb not null default '{}', updated_at timestamptz not null default now());
create table public.analytics_events (id uuid primary key default gen_random_uuid(), event_type text not null check (event_type in ('page_view','gallery_view','download','contact')), gallery_id uuid references public.galleries(id) on delete set null, photo_id uuid references public.photos(id) on delete set null, session_id text, country text, device text check (device in ('mobile','tablet','desktop')), created_at timestamptz not null default now());
alter table public.comments enable row level security; alter table public.downloads enable row level security; alter table public.messages enable row level security; alter table public.settings enable row level security; alter table public.analytics_events enable row level security;
create policy "admins manage clients" on public.clients for all using (exists (select 1 from public.profiles p where p.id = auth.uid() and p.role in ('admin','editor')));
create policy "admins manage categories" on public.categories for all using (exists (select 1 from public.profiles p where p.id = auth.uid() and p.role in ('admin','editor')));
create policy "admins manage profiles" on public.profiles for all using (id = auth.uid());
create policy "admins read messages" on public.messages for select using (exists (select 1 from public.profiles p where p.id = auth.uid() and p.role in ('admin','editor')));
create policy "public submit messages" on public.messages for insert with check (true);
create policy "admins manage settings" on public.settings for all using (exists (select 1 from public.profiles p where p.id = auth.uid() and p.role = 'admin'));
create policy "public sees active categories" on public.categories for select using (active = true);
create policy "admins read analytics" on public.analytics_events for select using (exists (select 1 from public.profiles p where p.id = auth.uid() and p.role in ('admin','editor')));
create policy "public records analytics" on public.analytics_events for insert with check (true);
create index galleries_public_idx on public.galleries (published_at desc, sort_order) where visibility = 'public';
create index galleries_category_idx on public.galleries (category_id, event_date desc);
create index photos_gallery_idx on public.photos (gallery_id, sort_order);
create index analytics_created_idx on public.analytics_events (created_at desc, event_type);
create unique index favorites_client_unique on public.favorites (photo_id, client_id) where client_id is not null;
create unique index favorites_session_unique on public.favorites (photo_id, session_token) where session_token is not null;
create or replace function public.set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at = now(); return new; end; $$;
create trigger profiles_updated_at before update on public.profiles for each row execute function public.set_updated_at();
create trigger clients_updated_at before update on public.clients for each row execute function public.set_updated_at();
create trigger galleries_updated_at before update on public.galleries for each row execute function public.set_updated_at();
create trigger photos_updated_at before update on public.photos for each row execute function public.set_updated_at();
create trigger settings_updated_at before update on public.settings for each row execute function public.set_updated_at();
